Object.assign(I18N.en, {"nav.gemeinden": "For municipalities", "nav.unternehmen": "For businesses", "nav.unternehmen.lang": "For businesses", "nav.kontakt": "Contact", "hero.chip2": "Pilot: 3 months free, cancel anytime", "pf.label": "The platform", "pf.title": "What participation looks like.", "pf.lead": "Four building blocks that municipalities use often. The views are simplified examples with made-up content.", "pf.k.h": "Ideas on the map", "pf.k.p": "Residents place pins where they like something, where something bothers them or where something is missing. The administration sees at a glance where action is needed.", "pf.k.titel": "Map survey", "pf.k.blase": "Shade for the playground", "pf.k.blase2": "Idea · 18 supports", "pf.k.l1": "Idea", "pf.k.l2": "Problem", "pf.k.l3": "I like it", "pf.a.h": "Votes and surveys", "pf.a.p": "Ask questions, offer options to choose from and show the result transparently.", "pf.a.titel": "Vote", "pf.a.frage": "Which option for the school playground?", "pf.a.o1": "Option A: more green", "pf.a.o2": "Option B: play equipment", "pf.a.o3": "Abstain", "pf.a.fuss": "Result visible to everyone", "pf.m.h": "Issue reporting", "pf.m.p": "Report damage in public spaces with a photo and location. The processing status is visible to everyone.", "pf.m.titel0": "Report damage", "pf.m.titel": "Street lamp broken", "pf.m.kat": "Category: lighting", "pf.m.ort": "Location set on the map", "pf.m.s1": "Received", "pf.m.s2": "In progress", "pf.m.s3": "Done", "pf.b.h": "Participatory budget", "pf.b.p": "Residents distribute a fixed amount among projects. The budget must not be exceeded.", "pf.b.titel": "Participatory budget", "pf.b.verfuegbar": "Available", "pf.b.p1": "Drinking fountain at the school", "pf.b.p2": "Bicycle parking", "pf.b.p3": "Benches by the pond", "pf.b.p4": "Stage for the village fair", "pf.b.fuss": "Selected: CHF 39,000 of 50,000", "pf.demo": "View the full demo platform", "ablauf.title3": "Live in 3 steps", "ablauf3.s1.h": "Conversation and demo", "ablauf3.s1.p": "We clarify your municipality's needs and show you the platform live.", "ablauf3.s2.h": "Setup and training", "ablauf3.s2.p": "We set up the platform with your logo, your topics and a first project, and train your team.", "ablauf3.s3.h": "Launch and pilot", "ablauf3.s3.p": "The platform goes online. We personally support the first process for three months and take care of hosting, updates and support.", "ablauf3.s3.tag": "3 months free", "pilot.k.gross": "months<br>free", "pilot.k.zusatz": "Cancel anytime", "faq.q0": "What does the pilot cost, and can we end it?", "faq.a0": "The pilot is free for three months and can be cancelled at any time, with no contract. Afterwards, the platform costs €4,900 per year for municipalities with up to 5,000 inhabitants, as a fixed price with no setup fees, not subject to VAT. Swiss municipalities: 4'900 CHF per year, up to 5'000 inhabitants. For larger municipalities we prepare an offer on request."});
Object.assign(I18N.fr, {"nav.gemeinden": "Pour les communes", "nav.unternehmen": "Pour les entreprises", "nav.unternehmen.lang": "Pour les entreprises", "nav.kontakt": "Contact", "hero.chip2": "Pilote : 3 mois gratuits, résiliable à tout moment", "pf.label": "La plateforme", "pf.title": "À quoi ressemble la participation.", "pf.lead": "Quatre modules souvent utilisés par les communes. Les vues sont des exemples simplifiés au contenu fictif.", "pf.k.h": "Des idées sur la carte", "pf.k.p": "Les habitantes et habitants placent des repères là où quelque chose leur plaît, les dérange ou manque. L'administration voit d'un coup d'œil où agir.", "pf.k.titel": "Enquête cartographique", "pf.k.blase": "Ombrager la place de jeux", "pf.k.blase2": "Idée · 18 soutiens", "pf.k.l1": "Idée", "pf.k.l2": "Problème", "pf.k.l3": "J'aime", "pf.a.h": "Votes et sondages", "pf.a.p": "Poser des questions, proposer des variantes et afficher le résultat en toute transparence.", "pf.a.titel": "Vote", "pf.a.frage": "Quelle variante pour la cour de récréation ?", "pf.a.o1": "Variante A : plus de verdure", "pf.a.o2": "Variante B : jeux", "pf.a.o3": "Abstention", "pf.a.fuss": "Résultat visible par tous", "pf.m.h": "Signalement de défauts", "pf.m.p": "Signaler des dégâts dans l'espace public avec photo et emplacement. L'état du traitement est visible par tous.", "pf.m.titel0": "Signaler un dégât", "pf.m.titel": "Lampadaire défectueux", "pf.m.kat": "Catégorie : éclairage", "pf.m.ort": "Emplacement placé sur la carte", "pf.m.s1": "Reçu", "pf.m.s2": "En cours", "pf.m.s3": "Réglé", "pf.b.h": "Budget participatif", "pf.b.p": "La population répartit un montant fixe entre des projets. Le budget ne doit pas être dépassé.", "pf.b.titel": "Budget participatif", "pf.b.verfuegbar": "Disponible", "pf.b.p1": "Fontaine près de l'école", "pf.b.p2": "Places pour vélos", "pf.b.p3": "Bancs près de l'étang", "pf.b.p4": "Scène pour la fête du village", "pf.b.fuss": "Sélectionné : CHF 39 000 sur 50 000", "pf.demo": "Voir toute la plateforme de démonstration", "ablauf.title3": "En ligne en 3 étapes", "ablauf3.s1.h": "Entretien et démo", "ablauf3.s1.p": "Nous clarifions les besoins de votre commune et vous montrons la plateforme en direct.", "ablauf3.s2.h": "Mise en place et formation", "ablauf3.s2.p": "Nous configurons la plateforme avec votre logo, vos thèmes et un premier projet, et formons votre équipe.", "ablauf3.s3.h": "Lancement et pilote", "ablauf3.s3.p": "La plateforme est mise en ligne. Nous accompagnons personnellement la première procédure pendant trois mois et nous occupons de l'hébergement, des mises à jour et du support.", "ablauf3.s3.tag": "3 mois gratuits", "pilot.k.gross": "mois<br>gratuits", "pilot.k.zusatz": "Résiliable à tout moment", "faq.q0": "Combien coûte le pilote et pouvons-nous l'arrêter ?", "faq.a0": "Le pilote est gratuit pendant trois mois et résiliable à tout moment, sans contrat. Ensuite, la plateforme coûte 4 900 € par an pour les communes jusqu'à 5 000 habitants, à prix fixe, sans frais de mise en place, non assujetti à la TVA. Communes suisses : 4'900 CHF par an, jusqu'à 5'000 habitants. Pour les communes plus grandes, offre sur demande."});
Object.assign(I18N.it, {"nav.gemeinden": "Per i comuni", "nav.unternehmen": "Per le aziende", "nav.unternehmen.lang": "Per le aziende", "nav.kontakt": "Contatto", "hero.chip2": "Progetto pilota: 3 mesi gratis, disdetta in qualsiasi momento", "pf.label": "La piattaforma", "pf.title": "Ecco come appare la partecipazione.", "pf.lead": "Quattro moduli usati spesso dai comuni. Le viste sono esempi semplificati con contenuti inventati.", "pf.k.h": "Idee sulla mappa", "pf.k.p": "Le abitanti e gli abitanti mettono segnaposti dove qualcosa piace, disturba o manca. L'amministrazione vede a colpo d'occhio dove intervenire.", "pf.k.titel": "Sondaggio su mappa", "pf.k.blase": "Ombreggiare il parco giochi", "pf.k.blase2": "Idea · 18 sostegni", "pf.k.l1": "Idea", "pf.k.l2": "Problema", "pf.k.l3": "Mi piace", "pf.a.h": "Votazioni e sondaggi", "pf.a.p": "Porre domande, proporre varianti e mostrare il risultato in modo trasparente.", "pf.a.titel": "Votazione", "pf.a.frage": "Quale variante per il cortile della scuola?", "pf.a.o1": "Variante A: più verde", "pf.a.o2": "Variante B: giochi", "pf.a.o3": "Astensione", "pf.a.fuss": "Risultato visibile a tutti", "pf.m.h": "Segnalazione di guasti", "pf.m.p": "Segnalare danni nello spazio pubblico con foto e posizione. Lo stato di elaborazione è visibile a tutti.", "pf.m.titel0": "Segnalare un danno", "pf.m.titel": "Lampione guasto", "pf.m.kat": "Categoria: illuminazione", "pf.m.ort": "Posizione indicata sulla mappa", "pf.m.s1": "Ricevuto", "pf.m.s2": "In corso", "pf.m.s3": "Risolto", "pf.b.h": "Bilancio partecipativo", "pf.b.p": "La popolazione ripartisce un importo fisso tra progetti. Il budget non può essere superato.", "pf.b.titel": "Bilancio partecipativo", "pf.b.verfuegbar": "Disponibile", "pf.b.p1": "Fontanella presso la scuola", "pf.b.p2": "Posteggi per bici", "pf.b.p3": "Panchine vicino allo stagno", "pf.b.p4": "Palco per la festa del paese", "pf.b.fuss": "Selezionato: CHF 39 000 su 50 000", "pf.demo": "Vedere tutta la piattaforma demo", "ablauf.title3": "Online in 3 passi", "ablauf3.s1.h": "Colloquio e demo", "ablauf3.s1.p": "Chiariamo le esigenze del vostro comune e vi mostriamo la piattaforma dal vivo.", "ablauf3.s2.h": "Configurazione e formazione", "ablauf3.s2.p": "Configuriamo la piattaforma con il vostro logo, i vostri temi e un primo progetto e formiamo il vostro team.", "ablauf3.s3.h": "Avvio e progetto pilota", "ablauf3.s3.p": "La piattaforma va online. Accompagniamo personalmente la prima procedura per tre mesi e ci occupiamo di hosting, aggiornamenti e supporto.", "ablauf3.s3.tag": "3 mesi gratis", "pilot.k.gross": "mesi<br>gratis", "pilot.k.zusatz": "Disdetta in qualsiasi momento", "faq.q0": "Quanto costa il progetto pilota e possiamo interromperlo?", "faq.a0": "Il progetto pilota è gratuito per tre mesi e disdicibile in qualsiasi momento, senza contratto. In seguito la piattaforma costa 4.900 € all'anno per i comuni fino a 5.000 abitanti, a prezzo fisso, senza costi di attivazione, non soggetto a IVA. Comuni svizzeri: 4'900 CHF all'anno, fino a 5'000 abitanti. Per i comuni più grandi, offerta su richiesta."});

